def health_check():
    """Health probe indicating server status."""
    return {"status": "ok", "project": settings.PROJECT_NAME, "version": settings.VERSION}

def readiness_check():
    """Readiness probe indicating model artifacts are loaded."""
    from src.services.predictor import predictor_service
    is_ready = predictor_service.model is not None and predictor_service.preprocessor.scaler is not None
    return {"status": "ready" if is_ready else "not_ready"}

def predict_transaction(transaction: TransactionInput):
    """Predicts risk for a single credit card transaction using the dual-model engine."""
    try:
        return predictor_service.predict(transaction)
    except Exception as e:
        logger.error(f"Prediction API internal error: {str(e)}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="An internal server error occurred during prediction processing."
        )

def predict_batch(transactions: List[TransactionInput]):
    """Batch prediction endpoint for scoring multiple transactions at once."""
    try:
        results = [predictor_service.predict(tx) for tx in transactions]
        logger.info(f"Processed batch prediction for {len(transactions)} transactions.")
        return results
    except Exception as e:
        logger.error(f"Batch Prediction API internal error: {str(e)}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="An internal server error occurred during batch prediction processing."
        )

class TransactionInput(BaseModel):
    Time: float = Field(..., ge=0, description="Seconds elapsed since first transaction")
    Amount: float = Field(..., ge=0, description="Transaction amount in Euros")
    v_features: List[float] = Field(
        ..., 
        min_length=28, 
        max_length=28, 
        description="List of 28 anonymized PCA feature values V1 to V28"
    )

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "Time": 0.0,
                "Amount": 149.62,
                "v_features": [
                    -1.359807, -0.072781, 2.536347, 1.378155,
                    -0.338321, 0.462388, 0.239599, 0.098698,
                    0.363787, 0.090794, -0.551600, -0.617801,
                    -0.991390, -0.311169, 1.468177, -0.470401,
                    0.207971, 0.025791, 0.403993, 0.251412,
                    -0.018307, 0.277838, -0.110474, 0.066928,
                    0.128539, -0.189115, 0.133558, -0.021053
                ]
            }
        }
    )

def _load_artifact(self, path: Path, description: str, optional: bool = False):
    try:
        logger.info(f"Loading {description} artifact from {path}")
        return joblib.load(path)
    except Exception as e:
        if optional:
            logger.warning(f"Optional artifact {description} not found at {path}: {e}")
            return None
        logger.error(f"Failed to load {description} from {path}: {e}")
        raise e

def _load_threshold(self) -> float:
    """Loads F2-optimized threshold from metadata.json (defaults to 0.5 if unavailable)."""
    try:
        if self.metadata_path.exists():
            with open(self.metadata_path, "r") as f:
                meta = json.load(f)
                threshold = float(meta.get("optimal_threshold", 0.5))
                logger.info(f"Loaded F2-optimized threshold: {threshold:.4f} from {self.metadata_path}")
                return threshold
    except Exception as e:
        logger.warning(f"Could not load metadata from {self.metadata_path}: {e}")
    return 0.5

class PreprocessorService:
    def __init__(self, scaler_path: Path):
        self.scaler_path = scaler_path
        self.scaler = self._load_scaler()

    def _load_scaler(self):
        try:
            logger.info(f"Loading scaler artifact from {self.scaler_path}")
            return joblib.load(self.scaler_path)
        except Exception as e:
            logger.error(f"Failed to load scaler from {self.scaler_path}: {e}")
            raise e

    def transform(self, transaction: TransactionInput) -> pd.DataFrame:
        """Constructs ordered feature vector and applies standard scaling."""
        feature_vector = [transaction.Time] + transaction.v_features + [transaction.Amount]
        df = pd.DataFrame([feature_vector], columns=FEATURE_NAMES)
        scaled_array = self.scaler.transform(df)
        return pd.DataFrame(scaled_array, columns=FEATURE_NAMES)

